        );
        let root = parsed.source_file.node_id.unwrap();
        let mut checker = crate::Checker::new(&bound, &parsed.nodes, &parsed.node_map);
        let callable = bound.lookup_local(root, "callable").unwrap();
        checker.defer_typeof_function_return(callable);
        let ty = checker.get_type_of_symbol(callable);
        let signature = checker.signature_types[&ty][0].clone();
        let key = checker.type_literal_key(signature.declaration);
        let original_parameter = checker.parameter_type(&signature.parameters[0]);
        let tsr_ast::Statement::TypeAliasDeclaration(alias) = parsed.source_file.statements[0]
        else {
            panic!("alias frame declaration");
        };
        let parameter = bound.symbol_of(alias.type_parameters[0].node_id.unwrap()).unwrap();
        let mut frame = rustc_hash::FxHashMap::default();
        frame.insert(parameter, checker.intrinsics.number);
        checker.alias_evaluation_bindings.push(frame);
        for _ in 0..3 {
            let shapes =
                checker.signature_shapes_of_type_kind(ty, super::SignatureKind::Call).unwrap();
            assert_eq!(shapes.len(), 1);
            assert_eq!(shapes[0].declaration, signature.declaration);
            assert_eq!(checker.parameter_type(&shapes[0].parameters[0]), original_parameter);
            assert!(checker.get_return_type_of_signature(&shapes[0]).is_none());
            assert!(checker.pending_signature_returns[&key] == super::LazyReturnState::Pending);
            assert!(!checker.signature_returns.contains_key(&key));
            let image = checker.intrinsics.string;
            assert_eq!(checker.instantiate_type(ty, &[(ty, image)], &[], &[]), image);
            assert_eq!(checker.instantiate_type(ty, &[], &[], &[]), checker.intrinsics.error);
            assert!(checker.instantiated_signatures.is_empty());
            assert!(checker.instantiated_objects.is_empty());
            assert_eq!(checker.get_type_of_symbol(callable), ty);
        }
        checker.alias_evaluation_bindings.pop();
        for _ in 0..3 {
            let selected = checker.resolve_call_signature(ty, None).unwrap();
            assert_eq!(checker.parameter_type(&selected.parameters[0]), original_parameter);
            assert_eq!(selected.r#type, checker.intrinsics.any);
            assert_eq!(checker.get_type_of_symbol(callable), ty);
            assert!(!checker.pending_signature_returns.contains_key(&key));
        }
        assert!(checker.diagnostics().is_empty());
    }

    #[test]
    fn callable_without_outer_parameters_maps_by_identity_without_forcing_metadata() {
        for function in [
            "function f(){return 1} namespace f {export const bar=1}",
            "function f():number{return 1} namespace f {export const bar=1}",
            "declare function f():number; namespace f {export const bar=1}",
            "function f<U>(u:U){return u} namespace f {export const bar=1}",
            "function f(){return 1}",
        ] {
            for checked_first in [false, true] {
                let source = format!("{function} interface Owner<T> {{self:this}}");
                let arena = tsr_core::Arena::new();
                let parsed = tsr_parser::parse(&arena, &source);
                assert!(parsed.diagnostics.is_empty());
                let bound = tsr_binder::bind(
                    &arena,
                    parsed.source_file,
                    &parsed.nodes,
                    tsr_binder::FileInfo { name: "admission.ts", text: &source },
                );
                let root = parsed.source_file.node_id.unwrap();
                let mut checker = crate::Checker::new(&bound, &parsed.nodes, &parsed.node_map);
                if checked_first {
                    checker.check_source_file(
                        root,
                        crate::check::FileContext { ambient: false, has_parse_errors: false },
                    );
                }
                let callable_symbol = bound.lookup_local(root, "f").unwrap();
                let callable = checker.get_type_of_symbol(callable_symbol);
                let owner_symbol = bound.lookup_local(root, "Owner").unwrap();
                let owner = checker.get_declared_type_of_symbol(owner_symbol);
                let this_node = (0..u32::try_from(parsed.nodes.len()).unwrap())
                    .find_map(|index| match parsed.node_map.get(tsr_ast::NodeId::new(index)) {
                        Some(tsr_ast::Node::ThisTypeNode(node)) => {
                            Some(tsr_ast::TypeNode::ThisTypeNode(node))
                        }
                        _ => None,
                    })
                    .unwrap();
                let formal_this = checker.get_type_from_type_node(this_node);
                assert!(
                    checker
                        .store
                        .get(formal_this)
                        .flags
                        .contains(crate::flags::TypeFlags::TYPE_PARAMETER)
                );
                let absent = !checker.signature_types.contains_key(&callable);
                if !checked_first && function.contains("namespace") {
                    assert!(absent, "the merged control must reach actual absent metadata");
                }
                for mapper in [vec![(formal_this, owner)], vec![(formal_this, formal_this)], vec![]]
                {
                    let snapshot = source_view_snapshot(&checker);
                    for _ in 0..3 {
                        assert_eq!(
                            checker.instantiate_type(callable, &mapper, &[formal_this], &["this"]),
                            callable,
                            "native retains {function}, checked_first={checked_first}, absent={absent}"
                        );
                        assert_eq!(
                            source_view_snapshot(&checker),
                            snapshot,
                            "identity mapping must leave signatures and return deferred"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn absent_callable_identity_keeps_pending_active_and_alias_contexts_ineligible() {
        let source = "type Frame<T>=T; function f(){return 1} namespace f {export const bar=1}";
        for state in ["pending", "active", "resolution", "alias"] {
            let arena = tsr_core::Arena::new();
            let parsed = tsr_parser::parse(&arena, source);
