package checker
import("fmt";"github.com/microsoft/typescript-go/internal/ast")
func(c *Checker) NativeAdmissionBudget(fn *ast.Node,depth,count uint32,nilMapper bool) map[string]any {
 t:=c.getTypeOfSymbol(c.getMergedSymbol(fn.Symbol()))
 before:=map[string]any{"members_resolved":t.objectFlags&ObjectFlagsMembersResolved!=0,"signature_count":len(t.AsStructuredType().signatures)}
 c.instantiationDepth=depth;c.instantiationCount=count
 saved:=c.currentNode;c.currentNode=fn;defer func(){c.currentNode=saved}()
 var mapper *TypeMapper;if !nilMapper {mapper=newTypeMapper([]*Type{c.numberType},[]*Type{c.stringType})}
 image:=c.instantiateTypeWithAlias(t,mapper,nil)
 return map[string]any{"checker":fmt.Sprintf("%p",c),"type_id":uint32(t.id),"image_id":uint32(image.id),"error":image==c.errorType,"same_identity":image==t,"depth_before":depth,"count_before":count,"depth_after":c.instantiationDepth,"count_after":c.instantiationCount,"nil_mapper":nilMapper,"before":before,"members_resolved_after":t.objectFlags&ObjectFlagsMembersResolved!=0,"signature_count_after":len(t.AsStructuredType().signatures)}
}

sources.native_admission_budget_test.go:
package checker_test
import("encoding/json";"fmt";"testing";"github.com/microsoft/typescript-go/internal/ast";"github.com/microsoft/typescript-go/internal/bundled";"github.com/microsoft/typescript-go/internal/compiler";"github.com/microsoft/typescript-go/internal/core";"github.com/microsoft/typescript-go/internal/tsoptions";"github.com/microsoft/typescript-go/internal/vfs/vfstest")
func TestNativeAdmissionBudget(t *testing.T){
 for _,budget:=range [][2]uint32{{0,0},{100,0},{0,5_000_000}} {for _,nilMapper:=range []bool{false,true} {t.Run(fmt.Sprintf("%d-%d-%v",budget[0],budget[1],nilMapper),func(t *testing.T){
  fs:=bundled.WrapFS(vfstest.FromMap(map[string]string{"/input.ts":"function f(){} namespace f {export const bar=1}","/tsconfig.json":`{"compilerOptions":{"types":[],"skipLibCheck":true,"noEmit":true,"singleThreaded":true},"files":["input.ts"]}`},false))
  host:=compiler.NewCompilerHost("/",fs,bundled.LibPath(),nil,nil);config,errors:=tsoptions.GetParsedCommandLineOfConfigFile("/tsconfig.json",&core.CompilerOptions{},nil,host,nil);if len(errors)!=0{t.Fatal(errors)}
  p:=compiler.NewProgram(compiler.ProgramOptions{Config:config,Host:host});p.BindSourceFiles();file:=p.GetSourceFile("/input.ts");var fn *ast.Node
  file.ForEachChild(func(n *ast.Node)bool{if n.Kind==ast.KindFunctionDeclaration{fn=n};return false});if fn==nil{t.Fatal("function")}
  c,done:=p.GetTypeChecker(t.Context());defer done();row:=c.NativeAdmissionBudget(fn,budget[0],budget[1],nilMapper);row["program"]=fmt.Sprintf("%p",p);raw,_:=json.Marshal(row);t.Logf("NATIVE_BUDGET %s",raw)
  refused:=!nilMapper&&(budget[0]==100||budget[1]>=5_000_000);expectedCount:=budget[1];if !nilMapper&&!refused{expectedCount++}
  if row["error"]!=refused||row["same_identity"]==refused||row["depth_after"]!=budget[0]||row["count_after"]!=expectedCount||row["members_resolved_after"]!=false||row["signature_count_after"]!=0 {t.Fatal("budget/metadata transition",row)}
 })}}
}

