test='''
    #[test]
    fn absent_callable_identity_keeps_pending_active_and_alias_contexts_ineligible() {
        let source="type Frame<T>=T; function f(){return 1} namespace f {export const bar=1}";
        for state in ["pending","active","resolution","alias"] {
            let arena=tsr_core::Arena::new();
            let parsed=tsr_parser::parse(&arena,source);
            assert!(parsed.diagnostics.is_empty());
            let bound=tsr_binder::bind(&arena,parsed.source_file,&parsed.nodes,
                tsr_binder::FileInfo{name:"states.ts",text:source});
            let root=parsed.source_file.node_id.unwrap();
            let mut checker=crate::Checker::new(&bound,&parsed.nodes,&parsed.node_map);
            let owner=bound.lookup_local(root,"f").unwrap();
            let ty=checker.get_type_of_symbol(owner);
            assert!(!checker.signature_types.contains_key(&ty));
            let declaration=bound.symbols().get(owner).declarations.iter().copied().find(|id|
                matches!(parsed.node_map.get(*id),Some(tsr_ast::Node::FunctionDeclaration(_)))).unwrap();
            let key=checker.type_literal_key(declaration);
            // Explicit admission fault controls use the real parsed owner/type;
            // these state injections are not natural return-resolution traces.
            match state {
                "pending"=>{checker.pending_signature_returns.insert(key.clone(),super::LazyReturnState::Pending);},
                "active"=>{checker.pending_signature_returns.insert(key.clone(),super::LazyReturnState::Active);},
                "resolution"=>{assert!(checker.resolutions.push(crate::resolution::ResolutionTarget::Signature(key.clone()),crate::resolution::PropertyName::ResolvedReturnType));},
                "alias"=>{
                    let tsr_ast::Statement::TypeAliasDeclaration(alias)=parsed.source_file.statements[0] else {panic!("alias")};
                    let parameter=bound.symbol_of(alias.type_parameters[0].node_id.unwrap()).unwrap();
                    checker.alias_evaluation_bindings.push([(parameter,checker.intrinsics.number)].into_iter().collect());
                },
                _=>unreachable!(),
            }
            let image=checker.intrinsics.string;
            let before=source_view_snapshot(&checker);
            for _ in 0..3 {
                assert_eq!(checker.instantiate_type(ty,&[(ty,image)],&[],&[]),image,"direct hit {state}");
                assert_eq!(checker.instantiate_type(ty,&[],&[],&[]),checker.intrinsics.error,"unsupported admission {state}");
                assert_eq!(source_view_snapshot(&checker),before,"refusal must not publish {state}");
            }
            if state=="resolution" {assert!(checker.resolutions.pop());}
            if state=="alias" {checker.alias_evaluation_bindings.pop();}
            checker.pending_signature_returns.remove(&key);
            assert_eq!(checker.instantiate_type(ty,&[],&[],&[]),ty,"actual cold identity after fault state is removed");
            assert!(!checker.signature_types.contains_key(&ty));
        }
    }

    #[test]
    fn callable_mapping_keeps_outer_and_own_generic_parameters_distinct() {
        for (body,own) in [("function f(){return x}",false),("function f<U>(u:U){return u}",true)] {
            let source=format!("function outer<T>(x:T){{{body} return f}}");
            for return_first in [false,true] {
                let arena=tsr_core::Arena::new();let parsed=tsr_parser::parse(&arena,&source);
                assert!(parsed.diagnostics.is_empty());
                let bound=tsr_binder::bind(&arena,parsed.source_file,&parsed.nodes,tsr_binder::FileInfo{name:"outer.ts",text:&source});
                let mut checker=crate::Checker::new(&bound,&parsed.nodes,&parsed.node_map);
                let tsr_ast::Statement::FunctionDeclaration(outer)=parsed.source_file.statements[0] else {panic!("outer")};
                let outer_signature=checker.get_signature_from_declaration(outer.node_id.unwrap()).unwrap();
                let parameters=checker.type_parameter_types(&outer_signature).unwrap();
                let function=(0..u32::try_from(parsed.nodes.len()).unwrap()).find_map(|index| {
                    let id=tsr_ast::NodeId::new(index);
                    matches!(parsed.node_map.get(id),Some(tsr_ast::Node::FunctionDeclaration(n)) if n.name.is_some_and(|name|name.text=="f")).then_some(id)
                }).unwrap();
                let original=checker.get_type_of_symbol(bound.symbol_of(function).unwrap());
                if return_first {let sig=checker.resolve_call_signature(original,None).unwrap();checker.get_return_type_of_signature(&sig).unwrap();}
                for _ in 0..3 {
                    let number=checker.intrinsics.number;
                    let mapped=checker.instantiate_type(original,&[(parameters[0],number)],&parameters,&["T"]);
                    assert_ne!(mapped,checker.intrinsics.error,"outer mapping must remain supported");
                    let signature=checker.resolve_call_signature(mapped,None).unwrap();
                    let returned=checker.get_return_type_of_signature(&signature).unwrap();
                    if own {
                        assert_eq!(signature.type_parameters.len(),1);
                        assert_eq!(returned,checker.parameter_type(&signature.parameters[0]));
                        assert_ne!(returned,number,"own U cannot become outer T's image");
                    } else {assert_eq!(returned,number,"outer T must become number");}
                }
            }
        }
    }

